<script setup lang="ts">
const finance = useFinance(); const fromAccountId = ref(''); const toAccountId = ref(''); const amount = ref<number | null>(null); const date = ref(new Date().toISOString().slice(0, 10)); const note = ref(''); const error = ref(''); const saving = ref(false)
const activeAccounts = computed(() => finance.accounts.value.filter(account => !account.isArchived))
async function save() { if (!amount.value) return; saving.value = true; error.value = ''; try { await finance.createTransfer({ fromAccountId: fromAccountId.value, toAccountId: toAccountId.value, amount: amount.value, transferDate: new Date(`${date.value}T12:00:00+07:00`).toISOString(), note: note.value }); await navigateTo('/transactions') } catch (cause) { error.value = (cause as { data?: { message?: string } })?.data?.message ?? 'Could not move money' } finally { saving.value = false } }
onMounted(async () => { await finance.refresh().catch(() => undefined); fromAccountId.value ||= activeAccounts.value[0]?.id ?? ''; toAccountId.value ||= activeAccounts.value[1]?.id ?? '' })
</script>
<template><main class="page"><NuxtLink to="/accounts" class="text-link">← Accounts</NuxtLink><div class="eyebrow" style="margin-top:26px">One balance to another</div><h1 class="display">Move money.</h1><p class="muted">Transfers change account balances, never income or spending totals.</p><div v-if="activeAccounts.length < 2" class="notice error">Create at least two active accounts before moving money.</div><form v-else class="form" @submit.prevent="save"><div class="transfer-route"><div class="field"><label>From</label><select v-model="fromAccountId" required><option v-for="account in activeAccounts" :key="account.id" :value="account.id">{{ account.name }}</option></select></div><span>→</span><div class="field"><label>To</label><select v-model="toAccountId" required><option v-for="account in activeAccounts" :key="account.id" :value="account.id">{{ account.name }}</option></select></div></div><div class="grid-2"><div class="field"><label>Amount</label><input v-model.number="amount" type="number" min="0.01" step="0.01" required></div><div class="field"><label>Date</label><input v-model="date" type="date" required></div></div><div class="field"><label>Note</label><input v-model="note" placeholder="Optional"></div><p v-if="error" class="notice error">{{ error }}</p><button class="button accent button-block" :disabled="saving || fromAccountId === toAccountId">{{ saving ? 'Moving…' : 'Move money' }}</button></form></main></template>

